import{_ as s,a0 as i,w as p,s as y,I as r,x as a,a1 as o,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用開源搜索引擎 YaCy 的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"使用開源搜索引擎 YaCy 的技巧 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用開源搜索引擎 YaCy 的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用開源搜索引擎 YaCy 的技巧 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200210 Top hacks for the YaCy open source search engine","title":"使用開源搜索引擎 YaCy 的技巧","tag":"202002","desc":""},"relativePath":"202002/20200210 Top hacks for the YaCy open source search engine.md","filePath":"[post].md"}'),u={name:"202002/20200210 Top hacks for the YaCy open source search engine.md"};function d(C,t,m,f,Y,b){const e=i("Link");return p(),y("div",null,[t[28]||(t[28]=r("h1",{id:"使用開源搜索引擎-yacy-的技巧",tabindex:"-1"},[a("使用開源搜索引擎 YaCy 的技巧 "),r("a",{class:"header-anchor",href:"#使用開源搜索引擎-yacy-的技巧","aria-label":"Permalink to “使用開源搜索引擎 YaCy 的技巧”"},"​")],-1)),t[29]||(t[29]=r("blockquote",null,[r("p",null,"無需適應其他人的眼光，而是使用 YaCY 搜索引擎定義你想要的互聯網。")],-1)),t[30]||(t[30]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202002/23/115822jqkdyjwzdqwdad0y.jpg",alt:""})],-1)),r("p",null,[t[2]||(t[2]=a("在我以前介紹 ",-1)),o(e,{href:"https://linux.cn/article-11905-1.html"},{default:n(()=>[...t[0]||(t[0]=[a("YaCy 入門",-1)])]),_:1}),t[3]||(t[3]=a("的文章中講述過 ",-1)),o(e,{href:"https://yacy.net/"},{default:n(()=>[...t[1]||(t[1]=[a("YaCy",-1)])]),_:1}),t[4]||(t[4]=a(" 這個",-1)),t[5]||(t[5]=r("ruby",null,[a("對等"),r("rt",null,"peer-to-peer")],-1)),t[6]||(t[6]=a("式的搜索引擎是如何安裝和使用的。YaCy 最令人興奮的一點就是它事實上是一個本地客户端，全球範圍內的每一個 YaCy 用户都是構成整個這個分佈式搜索引擎架構的一個節點，這意味着每個用户都可以掌控自己的互聯網搜索體驗。",-1))]),r("p",null,[t[8]||(t[8]=a("Google 曾經提供過 google.com/linux 這樣的主題簡便方式以便快速篩選出和 Linux 相關的搜索內容，這個小功能受到了很多人的青睞，但 Google 最終還是在 2011 年的時候把它",-1)),o(e,{href:"https://www.linuxquestions.org/questions/linux-news-59/is-there-no-more-linux-google-884306/"},{default:n(()=>[...t[7]||(t[7]=[a("下線",-1)])]),_:1}),t[9]||(t[9]=a("了。",-1))]),t[31]||(t[31]=l('<p>而 YaCy 則讓自定義搜索引擎變得可能。</p><h3 id="自定義-yacy" tabindex="-1">自定義 YaCy <a class="header-anchor" href="#自定義-yacy" aria-label="Permalink to “自定義 YaCy”">​</a></h3><p>YaCy 安裝好之後，只需要訪問 <code>localhost:8090</code> 就可以使用了。要自定義搜索引擎，只需要點擊右上角的“<ruby>管理<rt>Administration</rt></ruby>”按鈕（它可能隱藏在小屏幕的菜單圖標中）。</p><p>你可以在管理面板中配置 YaCy 對系統資源的使用策略，以及如何跟其它的 YaCy 客户端進行交互。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-profiles.jpg" alt="YaCy profile selector" title="YaCy profile selector"></p><p>例如，點擊側欄中的“<ruby>第一步<rt>First steps</rt></ruby>”按鈕可以配置備用端口，以及設置 YaCy 對內存和硬盤的使用量；而“<ruby>監控<rt>Monitoring</rt></ruby>”面板則可以監控 YaCy 的運行狀況。大多數功能都只需要在面板上點擊幾下就可以完成了，例如以下幾個常用的功能。</p><h3 id="內網搜索應用" tabindex="-1">內網搜索應用 <a class="header-anchor" href="#內網搜索應用" aria-label="Permalink to “內網搜索應用”">​</a></h3>',7)),r("p",null,[t[11]||(t[11]=a("目前市面上也有不少公司推出了",-1)),o(e,{href:"https://en.wikipedia.org/wiki/Vivisimo"},{default:n(()=>[...t[10]||(t[10]=[a("內網搜索應用",-1)])]),_:1}),t[12]||(t[12]=a("，而 YaCy 可以免費為你提供一個。對於能夠通過 HTTP、FTP、Samba 等協議訪問的文件，YaCy 都可以進行索引，因此無論是作為私人的文件搜索還是企業內部的本地共享文件搜索，YaCy 都可以實現。它可以讓內部網絡中的用户使用你個人的 YaCy 實例來查找共享文件，於此同時保持對內部網絡以外的用户不可見。",-1))]),t[32]||(t[32]=l('<h3 id="網絡配置" tabindex="-1">網絡配置 <a class="header-anchor" href="#網絡配置" aria-label="Permalink to “網絡配置”">​</a></h3><p>YaCy 在默認情況下就支持隱私和隔離。點擊“<ruby>用例與賬號<rt>Use Case &amp; Account</rt></ruby>”頁面頂部的“<ruby>網絡配置<rt>Network Configuration</rt></ruby>”鏈接，即可進入網絡配置面板設置對等網絡。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-network-config.jpg" alt="YaCy network configuration" title="YaCy network configuration"></p><h3 id="爬取站點" tabindex="-1">爬取站點 <a class="header-anchor" href="#爬取站點" aria-label="Permalink to “爬取站點”">​</a></h3><p>YaCy 的分佈式運作方式決定了它對頁面的爬取是由用户驅動的。並沒有一個大型公司對整個互聯網上的所有可訪問頁面都進行搜索，對於 YaCy 來説也是這樣，一個站點只有在被用户指定爬取的前提下，才會被 YaCy 爬取並進入索引。</p><p>YaCy 客户端提供了兩種爬取頁面的方式：你可以手動爬取，並讓 YaCy 根據建議去爬取。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-advanced-crawler.jpg" alt="YaCy advanced crawler" title="YaCy advanced crawler"></p><h4 id="手動爬取" tabindex="-1">手動爬取 <a class="header-anchor" href="#手動爬取" aria-label="Permalink to “手動爬取”">​</a></h4><p>手動爬取是指由用户輸入指定的網站 URL 並啓動 YaCy 的爬蟲任務。只需要點擊“<ruby>高級爬蟲<rt>Advanced Crawler</rt></ruby>”並輸入計劃爬取的若干 URL，然後選擇頁面底部的“<ruby>進行遠程索引<rt>Do Remote indexing</rt></ruby>”選項，這個選項會讓客户端向互聯網廣播它要索引的 URL，可選地接受這些請求的客户端可以幫助你爬取這些 URL。</p><p>點擊頁面底部的“<ruby>開始新爬蟲任務<rt>Start New Crawl Job</rt></ruby>”按鈕就可以開始進行爬取了，我就是這樣對一些常用和有用站點進行爬取和索引的。</p><p>爬蟲任務啓動之後，YaCy 會將這些 URL 對應的頁面在本地生成和存儲索引。在高級模式下，也就是本地計算機允許 8090 端口流量進出時，全網的 YaCy 用户都可以使用到這一份索引。</p><h4 id="加入爬蟲網絡" tabindex="-1">加入爬蟲網絡 <a class="header-anchor" href="#加入爬蟲網絡" aria-label="Permalink to “加入爬蟲網絡”">​</a></h4><p>儘管一些非常敬業的 YaCy 高級用户已經強迫症般地在互聯網上爬取了很多頁面，但對於全網浩如煙海的頁面而言也只是滄海一粟。單個用户所擁有的資源遠不及很多大公司的網絡爬蟲，但大量 YaCy 用户如果聯合起來成為一個社區，能產生的力量就大得多了。只要開啓了 YaCy 的爬蟲請求廣播功能，就可以讓其它客户端參與進來爬取更多頁面。</p><p>只需要在“<ruby>高級爬蟲<rt>Advanced Crawler</rt></ruby>”面板中點擊頁面頂部的“<ruby>遠程爬取<rt>Remote Crawling</rt></ruby>”，勾選“<ruby>加載<rt>Load</rt></ruby>”旁邊的複選框，就可以讓你的客户端接受其它人發來的爬蟲任務請求了。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-remote-crawl-accept.jpg" alt="YaCy remote crawling" title="YaCy remote crawling"></p><h3 id="yacy-監控相關" tabindex="-1">YaCy 監控相關 <a class="header-anchor" href="#yacy-監控相關" aria-label="Permalink to “YaCy 監控相關”">​</a></h3><p>YaCy 除了作為一個非常強大的搜索引擎，還提供了很豐富的主題和用户體驗。你可以在“<ruby>監控<rt>Monitor</rt></ruby>”面板中監控 YaCy 客户端的網絡運行狀況，甚至還可以瞭解到有多少人從 YaCy 社區中獲取到了自己所需要的東西。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-monitor.jpg" alt="YaCy monitoring screen" title="YaCy monitoring screen"></p><h3 id="搜索引擎發揮了作用" tabindex="-1">搜索引擎發揮了作用 <a class="header-anchor" href="#搜索引擎發揮了作用" aria-label="Permalink to “搜索引擎發揮了作用”">​</a></h3><p>你使用 YaCy 的時間越長，就越會思考搜索引擎如何改變自己的視野，因為你對互聯網的體驗很大一部分來自於你在搜索引擎中一次次簡單查詢的結果。實際上，當你和不同行業的人交流時，可能會注意到每個人對“互聯網”的理解都有所不同。有些人會認為，互聯網的搜索引擎中充斥着各種廣告和推廣，同時也僅僅能從搜索結果中獲取到有限的信息。例如，假設有人不斷搜索關於關鍵詞 X 的內容，那麼大部分商業搜索引擎都會在搜索結果中提高關鍵詞 X 的權重，但與此同時，另一個關鍵詞 Y 的權重則會相對降低，從而讓關鍵詞 Y 被淹沒在搜索結果當中，即使這樣對完成特定任務更好。</p><p>就像在現實生活中一樣，走出虛擬的世界視野會讓你看到一個更廣闊的世界。嘗試使用 YaCy，看看你發現了什麼。</p><hr>',22)),r("p",null,[t[14]||(t[14]=a("via: ",-1)),o(e,{href:"https://opensource.com/article/20/2/yacy-search-engine-hacks"},{default:n(()=>[...t[13]||(t[13]=[a("https://opensource.com/article/20/2/yacy-search-engine-hacks",-1)])]),_:1})]),r("p",null,[t[19]||(t[19]=a("作者：",-1)),o(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[15]||(t[15]=[a("Seth Kenlon",-1)])]),_:1}),t[20]||(t[20]=a(" 選題：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[16]||(t[16]=[a("lujun9972",-1)])]),_:1}),t[21]||(t[21]=a(" 譯者：",-1)),o(e,{href:"https://github.com/HankChow"},{default:n(()=>[...t[17]||(t[17]=[a("HankChow",-1)])]),_:1}),t[22]||(t[22]=a(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[18]||(t[18]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[25]||(t[25]=a("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[23]||(t[23]=[a("LCTT",-1)])]),_:1}),t[26]||(t[26]=a(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:n(()=>[...t[24]||(t[24]=[a("Linux中國",-1)])]),_:1}),t[27]||(t[27]=a(" 榮譽推出",-1))])])}const x=s(u,[["render",d]]);export{T as __pageData,x as default};
